    story: "We place a perfectly poached egg on a bed of toasted nori strips atop crusty bread. When you break the yolk, it mixes with the soy sauce and seaweed, creating an instant, rich sauce.",
    category: "Toast & Quick Bites",
    tags: ["Vegetarian"],
    allergens: ["egg", "gluten", "soy"],
    difficulty: "Medium",
