    story: "Raw tuna in the morning? Yes. Diced sashimi-grade tuna tossed in sriracha mayo, served over warm seasoned rice with a perfectly soft-boiled egg. It's high protein, bracing, and incredibly savory.",
    category: "Bowls & Drinks",
