    story: "The classic bacon, egg, and cheese sandwich gets wrapped in the bright, minty, basil-like flavor of fresh shiso leaves. It cuts entirely through the heavy pork fat, making the sandwich feel instantly refined.",
    category: "Toast & Quick Bites",
